#include <vector>
#include <queue>
#include <cmath>
#include <limits>

struct Node {
    double x = 0.0;
    double y = 0.0;
    Node* parent = nullptr;
    float h_value = std::numeric_limits<float>::max();
    float g_value = 0.0;
    bool visited = false;
    std::vector<Node*> neighbors;

    float distance(const Node& other) const {
        return std::sqrt(std::pow(x - other.x, 2) + std::pow(y - other.y, 2));
    }
};

struct Graph {
    std::vector<Node> nodes;
};

std::vector<Node> a_star_search(Graph& graph, int start_idx, int end_idx) {
    if (start_idx < 0 || start_idx >= graph.nodes.size() || 
        end_idx < 0 || end_idx >= graph.nodes.size()) {
        return {};
    }

    if (start_idx == end_idx) {
        return {graph.nodes[start_idx]};
    }

    for (auto& node : graph.nodes) {
        node.visited = false;
        node.g_value = std::numeric_limits<float>::max();
        node.h_value = std::numeric_limits<float>::max();
        node.parent = nullptr;
    }

    Node* start_node = &graph.nodes[start_idx];
    Node* end_node = &graph.nodes[end_idx];

    start_node->g_value = 0.0f;
    start_node->h_value = start_node->distance(*end_node);

    auto compare = [](const Node* a, const Node* b) {
        return (a->g_value + a->h_value) > (b->g_value + b->h_value);
    };

    std::priority_queue<Node*, std::vector<Node*>, decltype(compare)> open_list(compare);
    open_list.push(start_node);

    while (!open_list.empty()) {
        Node* current = open_list.top();
        open_list.pop();

        if (current->visited) continue;
        current->visited = true;

        if (current == end_node) {
            std::vector<Node> path;
            Node* node = end_node;
            while (node != nullptr) {
                path.push_back(*node);
                node = node->parent;
            }
            std::reverse(path.begin(), path.end());
            return path;
        }

        for (Node* neighbor : current->neighbors) {
            if (neighbor->visited) continue;

            float tentative_g = current->g_value + current->distance(*neighbor);

            if (tentative_g < neighbor->g_value) {
                neighbor->parent = current;
                neighbor->g_value = tentative_g;
                neighbor->h_value = neighbor->distance(*end_node);
                open_list.push(neighbor);
            }
        }
    }

    return {};
}

int main() {
    Graph graph;
    graph.nodes.resize(3);
    graph.nodes[0].x = 0.0; graph.nodes[0].y = 0.0;
    graph.nodes[1].x = 1.0; graph.nodes[1].y = 1.0;
    graph.nodes[2].x = 2.0; graph.nodes[2].y = 2.0;

    graph.nodes[0].neighbors.push_back(&graph.nodes[1]);
    graph.nodes[1].neighbors.push_back(&graph.nodes[0]);
    graph.nodes[1].neighbors.push_back(&graph.nodes[2]);
    graph.nodes[2].neighbors.push_back(&graph.nodes[1]);

    auto path = a_star_search(graph, 0, 2);
    return path.size() == 3 ? 0 : 1;
}

